<?php	require_once('../../helpers/func_main.php');	require_once('../../conf_system.php');	require_once('classes/class_api.m.php');   	// Convert data to json    $data = json_decode(file_get_contents('php://input'),true); 
    //Parse data from JSON    $password   = md5($data["user"]["password"]); 	$userid     = $data["user"]["userid"];     $token     = $data["user"]["access_token"];
    //Set default values    $message='Success';    $statuscode=0;    $oauth_access_token = '';    // Create class object    $api = new API();    //Get the user id if exists    if (!$api->validateToken($userid, $token))    {        $message='Invalid token';        $statuscode=100;        http_response_code(401);    }    else    {            $userid = $api->editUserPassword($userid,$password);            $message='Success';            $statuscode=0;    }    $response=array();	$response["status"]=array();	$status =array(            "message" => $message,            "statuscode" => $statuscode        );    $response["status"] = $status;    http_response_code(200);    echo json_encode($response);?>